package com.realestate.moving;

// Only editable company fields enter the API; ID is generated by the server.
public class MovingCompanyRequest {
    private String companyName;
    private String email;
    private String phone;
    private String serviceAreas;
    private String description;
    private String availability;

    public MovingCompanyRequest() { }
    public String getCompanyName() { return companyName; }
    public void setCompanyName(String companyName) { this.companyName=companyName; }
    public String getEmail() { return email; }
    public void setEmail(String email) { this.email=email; }
    public String getPhone() { return phone; }
    public void setPhone(String phone) { this.phone=phone; }
    public String getServiceAreas() { return serviceAreas; }
    public void setServiceAreas(String serviceAreas) { this.serviceAreas=serviceAreas; }
    public String getDescription() { return description; }
    public void setDescription(String description) { this.description=description; }
    public String getAvailability() { return availability; }
    public void setAvailability(String availability) { this.availability=availability; }

    @com.fasterxml.jackson.annotation.JsonAnySetter
    public void rejectUnknown(String name,Object value) {
        throw new IllegalArgumentException("Unsupported request field: " + name);
    }
}
